() => {
  function parseColor(c) {
    const m = c.match(/rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?\)/);
    if (!m) return null;
    return { r: +m[1], g: +m[2], b: +m[3], a: m[4] === undefined ? 1 : +m[4] };
  }
  function lum(c) {
    const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
    return 0.2126 * f(c.r) + 0.7152 * f(c.g) + 0.0722 * f(c.b);
  }
  function ratio(c1, c2) {
    const L1 = lum(c1), L2 = lum(c2);
    return (Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05);
  }
  function effBg(el) {
    const stack = [];
    let cur = el;
    while (cur && cur !== document.documentElement) {
      const bg = parseColor(getComputedStyle(cur).backgroundColor);
      if (bg && bg.a > 0) stack.push(bg);
      cur = cur.parentElement;
    }
    let base = { r: 255, g: 255, b: 255, a: 1 };
    for (let i = stack.length - 1; i >= 0; i--) {
      const s = stack[i];
      base = { r: s.r * s.a + base.r * (1 - s.a), g: s.g * s.a + base.g * (1 - s.a), b: s.b * s.a + base.b * (1 - s.a), a: 1 };
    }
    return base;
  }
  function scan(el, label) {
    const cs = getComputedStyle(el);
    const fg = parseColor(cs.color);
    const bg = effBg(el);
    return { label, text: el.textContent.trim().slice(0, 30), fg: cs.color, bg: `rgb(${bg.r|0},${bg.g|0},${bg.b|0})`, ratio: +ratio(fg, bg).toFixed(2), fontSize: cs.fontSize, visible: el.getBoundingClientRect().height > 0 };
  }
  const out = { userBubble: [], aiCard: [] };
  // latest user bubble body
  const bodies = Array.from(document.querySelectorAll('div')).filter(d => d.childElementCount === 0 && d.textContent.trim() === '各客户类型的数量分布');
  const body = bodies[bodies.length - 1];
  if (body) {
    let bubble = body;
    while (bubble && bubble.parentElement) {
      const bg = parseColor(getComputedStyle(bubble).backgroundColor);
      if (bg && bg.a > 0 && bg.b > 100) break; // indigo-ish
      bubble = bubble.parentElement;
    }
    out.bubbleBg = getComputedStyle(bubble).backgroundColor;
    const q = (sel, txt) => Array.from(bubble.querySelectorAll(sel)).find(e => e.textContent.trim().startsWith(txt));
    const you = Array.from(bubble.querySelectorAll('*')).find(e => e.childElementCount === 0 && e.textContent.trim() === '你');
    const ts = Array.from(bubble.querySelectorAll('*')).find(e => e.childElementCount === 0 && /^\d{1,2}:\d{2}$/.test(e.textContent.trim()));
    const copy = Array.from(bubble.querySelectorAll('button')).find(e => e.textContent.includes('复制'));
    const edit = Array.from(bubble.querySelectorAll('button')).find(e => e.textContent.includes('再次编辑'));
    if (you) out.userBubble.push(scan(you, '你'));
    if (ts) out.userBubble.push(scan(ts, 'timestamp'));
    out.userBubble.push(scan(body, 'body'));
    if (copy) out.userBubble.push(scan(copy, '复制btn'));
    if (edit) out.userBubble.push(scan(edit, '再次编辑btn'));
  }
  // latest AI card: the query-result-card region after the user bubble
  const cards = Array.from(document.querySelectorAll('[role="region"], div')).filter(d => (d.getAttribute && d.getAttribute('aria-label') === 'query-result-card') || (d.className && String(d.className).includes('query-result')));
  const card = cards[cards.length - 1];
  if (card) {
    const title = Array.from(card.querySelectorAll('*')).find(e => e.childElementCount === 0 && e.textContent.trim().startsWith('智能数据分析助手'));
    if (title) out.aiCard.push(scan(title, 'AI title'));
    // first long paragraph
    const paras = Array.from(card.querySelectorAll('p, div')).filter(e => e.childElementCount === 0 && e.textContent.trim().length > 40);
    if (paras[0]) out.aiCard.push(scan(paras[0], 'AI body'));
    const demo = Array.from(card.querySelectorAll('*')).find(e => e.childElementCount === 0 && e.textContent.includes('演示数据'));
    if (demo) out.aiCard.push(scan(demo, 'demo notice'));
    const kpiVal = Array.from(card.querySelectorAll('*')).filter(e => e.childElementCount === 0 && /^[\d.,万%]+$/.test(e.textContent.trim()) && e.textContent.trim().length > 1);
    if (kpiVal[0]) out.aiCard.push(scan(kpiVal[0], 'KPI value'));
    const kpiLabel = Array.from(card.querySelectorAll('*')).find(e => e.childElementCount === 0 && e.textContent.trim().length > 2 && !/^[\d.,万%]+$/.test(e.textContent.trim()) && e.closest('div') && e.getBoundingClientRect().height > 0 && parseFloat(getComputedStyle(e).fontSize) >= 12 && e.textContent.includes('客户'));
    if (kpiLabel) out.aiCard.push(scan(kpiLabel, 'KPI label'));
    const th = card.querySelector('th');
