    const d = ctx.getImageData(0, 0, 1, 1).data;
    return { r: d[0], g: d[1], b: d[2], a: d[3] / 255 };
  }
  function lum(c) {
    const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
    return 0.2126 * f(c.r) + 0.7152 * f(c.g) + 0.0722 * f(c.b);
  }
  function ratio(a, b) { const L1 = lum(a), L2 = lum(b); return (Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05); }
  function effBg(el) {
    const stack = [];
    let cur = el;
    while (cur && cur !== document.documentElement) {
      const cs = getComputedStyle(cur);
      const bg = norm(cs.backgroundColor);
      if (bg.a > 0) stack.push(bg);
      if (cs.backgroundImage.includes('gradient')) {
        const cols = (cs.backgroundImage.match(/oklch\([^)]*\)|rgba?\([^)]*\)|#[0-9a-f]{3,8}/gi) || []).map(norm);
        if (cols.length) {
          const avg = cols.reduce((acc, c) => ({ r: acc.r + c.r / cols.length, g: acc.g + c.g / cols.length, b: acc.b + c.b / cols.length }), { r: 0, g: 0, b: 0 });
          stack.push({ ...avg, a: 1 });
        }
      }
      cur = cur.parentElement;
    }
    let base = { r: 255, g: 255, b: 255, a: 1 };
    for (let i = stack.length - 1; i >= 0; i--) {
      const s = stack[i];
      base = { r: s.r * s.a + base.r * (1 - s.a), g: s.g * s.a + base.g * (1 - s.a), b: s.b * s.a + base.b * (1 - s.a), a: 1 };
    }
    return base;
  }
  let h4 = null;
  for (let i = 0; i < 5 && !h4; i++) {
    h4 = Array.from(document.querySelectorAll('h4')).find(h => h.textContent.includes('线索量分布'));
    if (!h4) await new Promise(r => setTimeout(r, 400));
  }
  if (!h4) return { error: 'no h4' };
  let card = h4;
  while (card && !(card.textContent.includes('智能数据分析助手') && card.textContent.includes('明细数据集'))) card = card.parentElement;
  const low = [];
  const leaves = Array.from(card.querySelectorAll('*')).filter(e => e.childElementCount === 0 && e.textContent.trim() && e.getBoundingClientRect().height > 0);
  for (const e of leaves) {
    const fgRaw = norm(getComputedStyle(e).color);
    const bg = effBg(e);
    const fg = { r: fgRaw.r * fgRaw.a + bg.r * (1 - fgRaw.a), g: fgRaw.g * fgRaw.a + bg.g * (1 - fgRaw.a), b: fgRaw.b * fgRaw.a + bg.b * (1 - fgRaw.a) };
    const r = ratio(fg, bg);
    if (r < 3) low.push({ text: e.textContent.trim().slice(0, 22), ratio: +r.toFixed(2), fg: `rgb(${fg.r|0},${fg.g|0},${fg.b|0})`, bg: `rgb(${bg.r|0},${bg.g|0},${bg.b|0})`, fs: getComputedStyle(e).fontSize });
  }
  return { leafCount: leaves.length, lowCount: low.length, low };
}

